 82	/** Send a raw HTTP request over TCP and return the response status code. */
 83	function getRawStatus(host: string, port: number, rawRequest: string): Promise<number> {
 84	  return new Promise((resolve, reject) => {
 85	    const socket = createConnection({ host, port }, () => {
 86	      socket.write(rawRequest);
 87	    });
 88	    const chunks: Buffer[] = [];
 89	    socket.on('data', (chunk: Buffer) => {
 90	      chunks.push(chunk);
 91	      const sofar = Buffer.concat(chunks).toString('utf-8');
 92	      const m = sofar.match(/^HTTP\/\d\.\d (\d{3})/);
 93	      if (m) {
 94	        socket.destroy();
 95	        resolve(parseInt(m[1]!, 10));
 96	      }
 97	    });
 98	    socket.on('error', reject);
 99	    socket.on('close', () => {
100	      const sofar = Buffer.concat(chunks).toString('utf-8');

101	      const m = sofar.match(/^HTTP\/\d\.\d (\d{3})/);
102	      if (m) resolve(parseInt(m[1]!, 10));
103	      else reject(new Error('No HTTP status line received'));
104	    });
105	  });
106	}
